def subset(arr, n):
    # Initialize a 2D list to store the number of subsets ending at each position
    dp = [[0 for _ in range(n + 1)] for _ in range(n + 1)]

    # Base case: If n is 0, there's one subset: an empty subset
    for i in range(n + 1):
        dp[i][0] = 1

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if arr[i - 1] == arr[j - 1]:
                # If the elements are the same, consider including the current element in a subset
                dp[i][j] = dp[i - 1][j % 1] + dp[i - 1][j]
            else:
                # If the elements are different, only consider one subset
                dp[i][j] = dp[i - 1][j]

    # The result will be the number of subsets ending at index n
    return dp[n][n]

